<script>
import imagesData from '../data/images.json';

const IMAGE_NAMESPACE = 'default';

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 63) || 'image';
}

function clusterDisplayName(cluster) {
  return cluster?.spec?.displayName || cluster?.metadata?.name || cluster?.id || '';
}

export default {
  name: 'ImageImportPanel',

  data() {
    return {
      images: imagesData.images,
      clusters: [],
      selectedClusterId: '',
      selectedFamily: 'Alle',
      loadingClusters: true,
      importState: {},
      error: '',
    };
  },

  computed: {
    families() {
      return ['Alle', ...Array.from(new Set(this.images.map((image) => image.family)))];
    },

    visibleImages() {
      if (this.selectedFamily === 'Alle') {
        return this.images;
      }

      return this.images.filter((image) => image.family === this.selectedFamily);
    },

    selectedCluster() {
      return this.clusters.find((cluster) => cluster.id === this.selectedClusterId);
    },
  },

  async mounted() {
    await this.loadClusters();
  },

  methods: {
    async loadClusters() {
      this.loadingClusters = true;
      this.error = '';

      try {
        const clusters = await this.$store.dispatch('management/findAll', {
          type: 'management.cattle.io.cluster',
        });

        this.clusters = (clusters || [])
          .filter((cluster) => this.isMsvCluster(cluster))
          .map((cluster) => ({
            id: cluster?.metadata?.name || cluster?.id,
            name: clusterDisplayName(cluster),
            raw: cluster,
          }))
          .sort((a, b) => a.name.localeCompare(b.name));

        const routeCluster = this.$route?.params?.cluster;
        const routeMatch = this.clusters.find((cluster) => cluster.id === routeCluster);

        this.selectedClusterId = routeMatch?.id || this.clusters[0]?.id || '';
      } catch (e) {
        this.error = `MSV-Cluster konnten nicht geladen werden: ${e?.message || e}`;
      } finally {
        this.loadingClusters = false;
      }
    },

    isMsvCluster(cluster) {
      const labels = cluster?.metadata?.labels || {};
      const annotations = cluster?.metadata?.annotations || {};

      return labels['cattle.io/distro-name'] === 'harvester' &&
        labels['msv.cloud.focusnet.de/cluster-id'] &&
        annotations['provisioner.cattle.io/ui-cluster-type'] === 'harvester';
    },

    statusFor(image) {
      return this.importState[image.id] || {};
    },

    async importImage(image) {
      if (!this.selectedClusterId) {
        this.error = 'Bitte wählen Sie zuerst einen MSV-Cluster aus.';
        return;
      }

      const name = slugify(image.resourceName || image.id);

      this.error = '';
      this.importState = {
        ...this.importState,
        [image.id]: { state: 'loading', message: 'Import wird gestartet ...' },
      };

      try {
        const body = {
          apiVersion: 'harvesterhci.io/v1beta1',
          kind: 'VirtualMachineImage',
          metadata: {
            name,
            namespace: IMAGE_NAMESPACE,
            annotations: {
              'harvesterhci.io/imageDisplayName': image.name,
              'msv.cloud.focusnet.de/source': 'focusnet-cloud-services-marketplace',
            },
            labels: {
              'msv.cloud.focusnet.de/catalog-image': image.id,
              'msv.cloud.focusnet.de/image-family': slugify(image.family),
            },
          },
          spec: {
            backend: 'backingimage',
            displayName: image.name,
            description: image.description || '',
            sourceType: 'download',
            url: image.sourceUrl,
          },
        };

        await this.$store.dispatch('management/request', {
          url: `/k8s/clusters/${this.selectedClusterId}/apis/harvesterhci.io/v1beta1/namespaces/${IMAGE_NAMESPACE}/virtualmachineimages`,
          method: 'POST',
          data: body,
        });

        this.importState = {
          ...this.importState,
          [image.id]: { state: 'success', message: 'Import im Cluster gestartet.' },
        };
      } catch (e) {
        const status = e?.response?.status || e?.status;
        const exists = status === 409;

        this.importState = {
          ...this.importState,
          [image.id]: {
            state: exists ? 'success' : 'error',
            message: exists ? 'Image existiert bereits im Cluster.' : `Import fehlgeschlagen: ${e?.message || e}`,
          },
        };
      }
    },
  },
};
</script>

<template>
  <section class="image-import">
    <header class="image-import__header">
      <div>
        <h2>MSV Images in Cluster laden</h2>
        <p>
          Wählen Sie ein Standard-Image aus. Der ausgewählte MSV-Cluster lädt das Image direkt aus dem focusnet Image-Repository.
        </p>
      </div>
      <button
        class="image-import__refresh"
        type="button"
        @click="loadClusters"
      >
        <i class="icon icon-refresh" />
        Aktualisieren
      </button>
    </header>

    <div
      v-if="error"
      class="image-import__error"
    >
      {{ error }}
    </div>

    <div class="image-import__toolbar">
      <label>
        <span>MSV-Cluster</span>
        <select
          v-model="selectedClusterId"
          :disabled="loadingClusters || clusters.length === 0"
        >
          <option
            v-if="clusters.length === 0"
            value=""
          >
            Keine berechtigten MSV-Cluster gefunden
          </option>
          <option
            v-for="cluster in clusters"
            :key="cluster.id"
            :value="cluster.id"
          >
            {{ cluster.name }}
          </option>
        </select>
      </label>

      <label>
        <span>Image-Typ</span>
        <select v-model="selectedFamily">
          <option
            v-for="family in families"
            :key="family"
            :value="family"
          >
            {{ family }}
          </option>
        </select>
      </label>
    </div>

    <div class="image-import__grid">
      <article
        v-for="image in visibleImages"
        :key="image.id"
        class="image-card"
      >
        <div class="image-card__topline">
          <span class="image-card__family">{{ image.family }}</span>
          <span class="image-card__format">{{ image.format }}</span>
        </div>
        <h3>{{ image.name }}</h3>
        <p>{{ image.description }}</p>
        <dl>
          <div>
            <dt>Version</dt>
            <dd>{{ image.version }}</dd>
          </div>
          <div v-if="image.language">
            <dt>Sprache</dt>
            <dd>{{ image.language }}</dd>
          </div>
          <div v-if="image.size">
            <dt>Größe</dt>
            <dd>{{ image.size }}</dd>
          </div>
        </dl>
        <button
          class="image-card__button"
          type="button"
          :disabled="!selectedClusterId || statusFor(image).state === 'loading'"
          @click="importImage(image)"
        >
          <i class="icon icon-download" />
          {{ statusFor(image).state === 'loading' ? 'Starte ...' : 'In Cluster laden' }}
        </button>
        <p
          v-if="statusFor(image).message"
          :class="['image-card__status', `image-card__status--${statusFor(image).state}`]"
        >
          {{ statusFor(image).message }}
        </p>
      </article>
    </div>
  </section>
</template>

