<script>
export default {
  name: 'AddOnCard',

  props: {
    addon: {
      type:     Object,
      required: true,
    },
  },

  computed: {
    iconClasses() {
      return ['icon', this.addon.iconClass || 'icon-cloud'];
    },
    isComingSoon() {
      return Boolean(this.addon.comingSoon);
    },
  },
};
</script>

<template>
  <article class="addon-card">
    <header class="addon-card__header">
      <i :class="iconClasses" />
      <h2 class="addon-card__title">
        {{ addon.name }}
      </h2>
      <span
        v-if="isComingSoon"
        class="addon-card__badge addon-card__badge--soon"
      >
        Bald verfuegbar
      </span>
    </header>

    <p class="addon-card__short">
      {{ addon.shortDescription }}
    </p>

    <p class="addon-card__long">
      {{ addon.longDescription }}
    </p>

    <ul
      v-if="addon.features && addon.features.length"
      class="addon-card__features"
    >
      <li
        v-for="feature in addon.features"
        :key="feature"
      >
        {{ feature }}
      </li>
    </ul>

    <div class="addon-card__pricing">
      <strong>Preise:</strong> {{ addon.pricing }}
    </div>

    <div class="addon-card__actions">
      <a
        v-if="!isComingSoon"
        :href="addon.portalUrl"
        target="_blank"
        rel="noopener noreferrer"
        class="addon-card__cta"
      >
        {{ addon.buttonLabel || 'Im Kundenportal bestellen' }}
        <i class="icon icon-chevron-right" />
      </a>
      <span
        v-else
        class="addon-card__cta addon-card__cta--disabled"
      >
        In Vorbereitung
      </span>
    </div>
  </article>
</template>

