<script>
import addonsData from './data/addons.json';
import AddOnCard from './components/AddOnCard.vue';
import ImageImportPanel from './components/ImageImportPanel.vue';

export default {
  name: 'Marketplace',

  layout: 'plain',

  components: { AddOnCard, ImageImportPanel },

  data() {
    return {
      addons:        addonsData.addons,
      clusterLabels: {},
    };
  },

  computed: {
    visibleAddons() {
      return this.addons.filter((addon) => {
        const gate = addon.clusterLabelGate;

        if (!gate || !gate.hideWhenSetOnAnyCluster) {
          return true;
        }

        const labelValue = this.clusterLabels[gate.key];

        return labelValue !== gate.value;
      });
    },
  },

  async mounted() {
    try {
      const clusters = await this.$store.dispatch('management/findAll', {
        type: 'management.cattle.io.cluster',
      });

      const merged = {};

      (clusters || []).forEach((c) => {
        const labels = c?.metadata?.labels || {};

        Object.entries(labels).forEach(([k, v]) => {
          merged[k] = v;
        });
      });

      this.clusterLabels = merged;
    } catch (e) {
      // Ignore - alle Add-Ons werden gezeigt wenn wir Cluster-Labels nicht laden koennen
      // (z.B. weil der eingeloggte User keine list-Permission hat)
    }
  },
};
</script>

<template>
  <div class="marketplace">
    <header class="marketplace__header">
      <h1>focusnet Cloud Services Marketplace</h1>
      <p class="marketplace__subtitle">
        Erweitern Sie Ihre Kubernetes-Plattform um buchbare Services. Klicken Sie auf einen Eintrag, um ihn im Kundenportal zu bestellen.
      </p>
    </header>

    <div class="marketplace__grid">
      <AddOnCard
        v-for="addon in visibleAddons"
        :key="addon.id"
        :addon="addon"
      />
    </div>

    <ImageImportPanel />

    <footer class="marketplace__footer">
      <p>
        Sie vermissen einen Service?
        <a
          href="mailto:vertrieb@focusnet.de"
          class="marketplace__contact"
        >Sprechen Sie uns an</a>
        — wir erweitern den Marketplace laufend.
      </p>
    </footer>
  </div>
</template>

