import { IPlugin } from '@shell/core/types';

export const NAME = 'cloud-services-marketplace';

export function init($plugin: IPlugin, store: any) {
  const { product } = $plugin.DSL(store, NAME);

  product({
    inStore:             'management',
    icon:                'compass',
    label:               'focusnet Cloud Services Marketplace',
    removable:           false,
    showClusterSwitcher: false,
    category:            'global',
    to:                  { name: 'cloud-services-marketplace' },
  } as any);
}
